mapper.select:
SELECT p.id AS patientId, p.name AS patientName, p.gender_enum AS genderEnum, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, r.encounter_id AS encounterBusNo, r.requester_id AS requesterName, COUNT(r.id) AS drugCount, MIN(r.req_authored_time) AS encounterTime FROM med_medication_request r JOIN adm_patient p ON p.id = r.patient_id WHERE r.is_deleted = 0 AND r.intent_enum = 'OUTPATIENT' AND r.status_enum = 'PENDING'
AND p.name LIKE CONCAT('%', #{query.name}, '%')
AND p.py_str LIKE CONCAT('%', #{query.pyStr}, '%')
AND r.location_id = #{query.locationId}
AND r.req_authored_time BETWEEN #{query.startTime} AND #{query.endTime}
GROUP BY p.id, r.encounter_id
